import type { SupabaseClient } from '@supabase/supabase-js'

/**
 * Commercial financial reconciliation only. No clinical records, patient PII,
 * payment amount from a browser, or unverified webhook payload is accepted.
 */
export const GENERAL_PHARMACY_BR_PRICE_CENTS = 7900
export const JORDAN_REFERRAL_CENTS = 1000
// Shared BR pharmacy express doctor fee, with or without Jordan attribution.
// No doctor payout is generated by these accounting constants.
export const JORDAN_DOCTOR_FEE_CENTS = 4000
export const JORDAN_PRE_COST_MARGIN_CENTS = GENERAL_PHARMACY_BR_PRICE_CENTS - JORDAN_REFERRAL_CENTS - JORDAN_DOCTOR_FEE_CENTS // first acquisition only
export const DIRECT_PHARMACY_PRE_COST_MARGIN_CENTS = GENERAL_PHARMACY_BR_PRICE_CENTS - JORDAN_DOCTOR_FEE_CENTS

export interface VerifiedPharmacyProviderPayment {
  id: string | number
  status: string
  status_detail?: string | null
  transaction_amount: number
  transaction_amount_refunded?: number | null
  currency_id: string
  external_reference?: string | null
  date_approved?: string | null
  metadata?: Record<string, unknown> | null
}

export interface LocalPharmacyPayment {
  id: string
  dispatch_request_id: string
  provider_payment_id: string | null
  amount_minor: number
  currency: string
  status: string
  provider: string
}

export function classifyVerifiedPharmacyPayment(
  local: LocalPharmacyPayment,
  payment: VerifiedPharmacyProviderPayment,
): 'pending' | 'approved' | 'rejected' | 'cancelled' | 'refunded' | null {
  const providerId = String(payment.id)
  if (!/^\d{1,20}$/.test(providerId)) return null
  if (local.provider !== 'mercadopago' || local.currency !== 'BRL') return null
  if (local.provider_payment_id && local.provider_payment_id !== providerId) return null
  if (payment.currency_id !== 'BRL') return null
  if (local.amount_minor !== Math.round(payment.transaction_amount * 100)) return null
  if (payment.external_reference !== `pharm:${local.dispatch_request_id}`) return null
  if (payment.metadata?.payment_type !== 'pharmacy_consultation' ||
      payment.metadata?.dispatch_id !== local.dispatch_request_id) return null

  // Any refund voids eligibility; a partially refunded payment is NOT a full sale.
  if ((payment.transaction_amount_refunded ?? 0) > 0 ||
      payment.status_detail === 'partially_refunded' ||
      payment.status === 'refunded' || payment.status === 'charged_back') return 'refunded'

  if (payment.status === 'approved' && payment.date_approved) return 'approved'
  if (payment.status === 'pending' || payment.status === 'in_process' ||
      payment.status === 'authorized') return 'pending'
  if (payment.status === 'rejected') return 'rejected'
  if (payment.status === 'cancelled' || payment.status === 'canceled') return 'cancelled'
  return null
}

export async function reconcilePharmacyProviderPayment(
  admin: SupabaseClient,
  payment: VerifiedPharmacyProviderPayment,
): Promise<{ handled: boolean; reason?: string }> {
  const dispatchId = typeof payment.metadata?.dispatch_id === 'string'
    ? payment.metadata.dispatch_id : ''
  const validRef = /^pharm:([0-9a-f-]{36})$/i.exec(payment.external_reference ?? '')
  if (validRef?.[1] !== dispatchId) {
    return { handled: false, reason: 'unmatched_pharmacy_payment_reference' }
  }

  const { data: row, error } = await admin
    .from('pharmacy_dispatch_payments')
    .select('id,dispatch_request_id,provider_payment_id,amount_minor,currency,status,provider')
    .eq('dispatch_request_id', dispatchId)
    .maybeSingle()
  if (error) throw error
  if (!row) {
    // Do NOT fabricate a payment row based on a webhook's claimed metadata.
    return { handled: false, reason: 'pharmacy_checkout_not_found' }
  }

  const next = classifyVerifiedPharmacyPayment(row as LocalPharmacyPayment, payment)
  if (!next) return { handled: false, reason: 'pharmacy_payment_evidence_mismatch' }
  if (row.status === 'refunded' ||
      (row.status === 'approved' && next === 'pending')) {
    return { handled: true }
  }
  // Reconciliation is idempotent via dispatch_request_id, provider_payment_id
  // uniqueness and the DB trigger's single commission row per dispatch.
  const { error: updateError } = await admin.from('pharmacy_dispatch_payments')
    .update({
      status: next,
      provider_payment_id: String(payment.id),
      paid_at: next === 'approved' ? payment.date_approved : null,
      updated_at: new Date().toISOString(),
    })
    .eq('id', row.id)
    .eq('dispatch_request_id', dispatchId)
    .in('status', ['initializing','pending','approved','rejected','cancelled'])
  if (updateError) throw updateError

  return { handled: true }
}
